// Next.js biến cây thư mục thành đường dẫn website.
// Hàm này mô phỏng ý tưởng đó:
function fileToRoute(file) {
  return (
    "/" +
    file
      .replace(/^app\/?/, "")
      .replace(/\/?page\.js$/, "")
      .replace(/\[(\w+)\]/g, ":$1")
  );
}

console.log(fileToRoute("app/page.js"));                 // /
console.log(fileToRoute("app/about/page.js"));           // /about
console.log(fileToRoute("app/blog/[slug]/page.js"));     // /blog/:slug

